package com.wingedsheep.engine.scenarios

import com.wingedsheep.engine.support.GameTestDriver
import com.wingedsheep.engine.support.TestCards
import com.wingedsheep.sdk.core.Color
import com.wingedsheep.sdk.core.Step
import com.wingedsheep.sdk.model.Deck
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe

/**
 * Plague Wind (PCY #74) — {7}{B}{B} Sorcery.
 *
 * "Destroy all creatures you don't control. They can't be regenerated."
 *
 * Generated by mtgish-tooling, whose target recovery collapsed the IR's
 * `ControlledByAPlayer(Other(You))` ("a player other than you") to `.youControl()` — so the sweeper
 * pointed at the caster's own board and left the opponent's untouched, the exact inverse of the card.
 */
class PlagueWindScenarioTest : FunSpec({

    fun newDriver(): GameTestDriver {
        val driver = GameTestDriver()
        driver.registerCards(TestCards.all)
        driver.initMirrorMatch(Deck.of("Swamp" to 40), skipMulligans = true, startingPlayer = 0)
        driver.passPriorityUntil(Step.PRECOMBAT_MAIN)
        return driver
    }

    test("destroys every creature the caster does not control, and none of their own") {
        val driver = newDriver()
        driver.putCreatureOnBattlefield(driver.player1, "Grizzly Bears")
        driver.putCreatureOnBattlefield(driver.player1, "Minotaur Warrior")
        driver.putCreatureOnBattlefield(driver.player2, "Grizzly Bears")
        driver.putCreatureOnBattlefield(driver.player2, "Minotaur Warrior")

        val wind = driver.putCardInHand(driver.player1, "Plague Wind")
        driver.giveMana(driver.player1, Color.BLACK, 9)
        driver.castSpell(driver.player1, wind).isSuccess shouldBe true
        driver.bothPass()

        driver.getCreatures(driver.player1).size shouldBe 2
        driver.getCreatures(driver.player2).size shouldBe 0
    }
})
